from datetime import date
def solve(start,end):
    return (date.fromisoformat(end)-date.fromisoformat(start)).days

from datetime import date,timedelta
def solve(day,months):
    return (date.fromisoformat(day)+timedelta(days=30*months)).isoformat()

from datetime import datetime
def solve(start,end):
    return (datetime.fromisoformat(end.replace('Z','+00:00'))-datetime.fromisoformat(start.replace('Z','+00:00'))).seconds

def solve(text):
    if not text.startswith('/'): raise ValueError('relative required')
    return text

import json
def solve(text):
    return json.loads(text)

def solve(text,needle):
    index=text.find(needle)
    return [index] if index>=0 else []
